CREATE VIEW [purchase].[PurchaseAnalysis] AS SELECT CONVERT(date,i.InvoiceDate)PurchaseDate,i.SupplierId,d.ProductId,SUM(d.Quantity+d.FreeQuantity-d.ReturnedQuantity)NetQuantity,SUM(d.LineTotal)GrossAmount,SUM(d.GSTAmount)GSTAmount FROM purchase.PurchaseInvoices i JOIN purchase.PurchaseInvoiceItems d ON d.PurchaseInvoiceId=i.PurchaseInvoiceId WHERE i.IsDeleted=0 AND i.Status NOT IN('DRAFT','CANCELLED') GROUP BY CONVERT(date,i.InvoiceDate),i.SupplierId,d.ProductId;
